  'con.field.email': {zh:`邮箱 / Email`, en:`Email`, fr:`E-mail`, de:`E-Mail`, es:`Correo`, ru:`Эл. почта`, ko:`이메일`, ar:`البريد`},
  'con.field.phone': {zh:`电话 / WhatsApp`, en:`Phone / WhatsApp`, fr:`Téléphone / WhatsApp`, de:`Telefon / WhatsApp`, es:`Teléfono / WhatsApp`, ru:`Телефон / WhatsApp`, ko:`전화 / WhatsApp`, ar:`هاتف / واتساب`},
  'con.field.country': {zh:`国家 / 地区`, en:`Country`, fr:`Pays`, de:`Land`, es:`País`, ru:`Страна`, ko:`국가`, ar:`البلد`},
  'con.field.treatment': {zh:`想咨询的疗法`, en:`Treatment of interest`, fr:`Traitement souhaité`, de:`Gewünschte Behandlung`, es:`Tratamiento`, ru:`Интересующее лечение`, ko:`관심 분야`, ar:`العلاج المطلوب`},
  'con.field.msg': {zh:`病情简述（可选）`, en:`Brief case summary (optional)`, fr:`Résumé (option)`, de:`Kurze Zusammenfassung (opt.)`, es:`Resumen (opcional)`, ru:`Кратко о случае (необ.)`, ko:`병력 요약 (선택)`, ar:`ملخص الحالة (اختياري)`},
  'con.btn': {zh:`提交咨询`, en:`Submit Consultation`, fr:`Envoyer`, de:`Absenden`, es:`Enviar`, ru:`Отправить`, ko:`상담 보내기`, ar:`إرسال الاستشارة`},
  'con.success': {zh:`已收到您的信息！我们将在 1–2 个工作日内与您联系。`, en:`We received your information! We will contact you within 1–2 business days.`, fr:`Demande reçue ! Réponse sous 1-2 jours.`, de:`Eingegangen! Antwort in 1–2 Tagen.`, es:`¡Recibido! Le responderemos en 1-2 días.`, ru:`Получили! Свяжемся за 1–2 дня.`, ko:`접수되었습니다! 1~2 영업일 내 연락드립니다.`, ar:`وصلنا طلبك! سنتواصل خلال 1-2 يوم عمل.`},
  'con.contact.title': {zh:`直接联系我们`, en:`Reach Us Directly`, fr:`Nous contacter`, de:`Direkt kontaktieren`, es:`Contáctenos`, ru:`Связаться напрямую`, ko:`바로 연락`, ar:`تواصل مباشر`},
